-- osha-pl-cs-scope-1 replaces osha-pl-cs-scope-1 (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-scope-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-scope-1", "title": "When the construction confined space rule applies, and when it does not", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926 Subpart AA (1926.1201 to 1926.1213, in effect since August 3, 2015) protects employees doing construction work at a site with one or more confined spaces. The rule's own examples include manholes, sewers, storm drains, pits, vaults, tanks, lift stations and pipe; on utility jobs manholes, vaults, wet wells and large pipes are typically confined spaces, and sewer manholes are usually permit spaces because of hydrogen sulfide, methane and low oxygen. It does not apply to construction work regulated by Subpart P (excavations), Subpart S (underground construction, caissons, cofferdams and compressed air) or Subpart Y (diving) (1926.1201(b)). So an open trench is under the excavation rule, but a manhole, a vault or the inside of a pipe is a confined space even when it sits in an excavation. Where another OSHA rule also covers a hazard in the space, follow both (1926.1201(c)). Maintenance work that is not construction is under the general industry rule, 29 CFR 1910.146. Before any entry use the company's written program and the app's confined space permit. A state with its own OSHA plan may have its own rule: see the confined space state tables.", "source": "29 CFR 1926.1201(a)-(c); OSHA Confined Spaces in Construction FAQ", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-silica-1 (retired: the plain overview; its program items are in osha-pl-cs-first-steps-1 / -program-1)."}$kb$::jsonb
 where version = 'b3e91f6c47d2' and chunk->>'id' = $kb$osha-pl-cs-scope-1$kb$
