update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-permit-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-permit-1", "title": "The entry permit: the 16 items and how long to keep it", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1206 lists what the permit identifies: (a) the space; (b) the purpose of entry; (c) the date and authorized duration; (d) the entrants, by name or by a roster or tracking system; (e) how a rise in air hazard is detected if ventilation stops; (f) each attendant by name; (g) each entry supervisor by name, with the signature or initials of each supervisor who authorizes entry; (h) the hazards of the space; (i) the isolation and control measures; (j) the acceptable entry conditions; (k) test results with the tester's name or initials and when; (l) rescue and emergency services and how to summon them; (m) communication procedures; (n) equipment: PPE, testing, communications, alarms, rescue; (o) other information needed for safety; (p) other permits, such as hot work. The supervisor signs before entry and \"The entry employer must retain each canceled entry permit for at least 1 year\" (1926.1205(b), (f)); the permit process card has posting, duration, cancel or suspend and problems noted.", "source": "29 CFR 1926.1205(b), (f); 1926.1206(a)-(p)", "url": "https://www.law.cornell.edu/cfr/text/29/1926.1206", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "The 1926.1205 process sentences moved to osha-pl-cs-permit-keep-1."}$kb$::jsonb
 where version = 'b3e91f6c47d2' and chunk->>'id' = $kb$osha-pl-cs-permit-1$kb$
