-- osha-pl-cs-altproc-1 replaces osha-pl-cs-altproc-1 (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-altproc-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-altproc-1", "title": "Alternate procedures: ventilation-only entry into a permit space, and when it is not allowed", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1203(e)(1): alternate procedures (no full permit) only when the employer shows all physical hazards are eliminated or isolated so the only hazard is the atmosphere, and continuous forced air ventilation alone keeps the space safe, backed by documented monitoring data available to entrants; an entry to get that data is a full permit entry. (e)(2): make it safe to open the cover and guard the opening; test before entry \"for oxygen content, for flammable gases and vapors, and for potential toxic air contaminants, in that order\"; no hazardous atmosphere while anyone is inside; forced air at the work area from a clean source, from before entry until all are out; continuous monitoring (periodic only under the exception); all out at once on a hazard; safe access; a written certification (date, location, signature) at the entrance. Any engulfment, machinery, electrical or other physical hazard, such as sewer flow that can surge, means a full permit. The entry supervisor and the company program decide; Ask does not.", "source": "29 CFR 1926.1203(e)(1)-(2)", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-field-numbers-6 (retired). The reclassification sentence moved to osha-pl-cs-reclass-1."}$kb$::jsonb
