update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-ca-confined-2026-1", "state": "CA", "tier": "core", "supersedes": "sp-ca-confined-2026-1", "title": "California confined space changes from January 1, 2026: site survey, testing, inerting and rescue at the site", "topic": "State safety plan: confined space", "text": "California amended 8 CCR 1951, 1952, 1953, 1955, 1956 and 1960 (and 5156) effective January 1, 2026 (filed November 4, 2025). Text approved by OAL (read 2026-11-21): a competent person must \"conduct an initial survey of its work area for confined spaces existing at the time work begins\" (1952(a)(1)) and inspect often enough to find new ones (1952(a)(2)); evaluation includes testing (1952(a)(4)); if flammables cannot be brought under 10 percent LFL, entry only after inerting, with PPE (1953(a)(3)(D)); the permit says how to summon rescue and emergency medical services (1955(a)(12)); and \"the rescue services at the site are trained, immediately available, properly equipped\" (1960(a)), with a note on a standby person able to rescue at once. Federal 1926.1211(a) accepts an evaluated service that can respond in a timely manner: follow California's stricter wording. Which words are new is not confirmed from the text (no underline); the Final Statement of Reasons (2025-09-18) shows no permit item change.", "source": "OSHSB rulemaking Confined Spaces in Construction: Text Approved by OAL; Final Statement of Reasons updated 2025-09-18; 8 CCR 1952, 1953, 1955, 1960", "url": "https://dir.ca.gov/OSHSB/documents/Confined-Spaces-in-Construction-OAL-Changes-Text.pdf", "checked": "2026-11-21", "edition": "Amendments effective 2026-01-01, filed 2025-11-04", "effective": "2026-01-01", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "yes", "note": "Rewritten from the OAL-approved text (read 2026-11-21); keeps every fact of the FSOR-based card."}$kb$::jsonb
