update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-ca-confined-air-1", "state": "CA", "tier": "core", "supersedes": "ca-cal-osha-trench-and-confined-3", "title": "California confined space air limits: Cal/OSHA CO 25 ppm and H2S 10 / 15 / 50 ppm (8 CCR 5155), stricter than federal", "topic": "State safety plan: confined space", "text": "California's permissible exposure limits (Title 8 section 5155, Table AC-1) are stricter than federal for gases crews meet in manholes and vaults. Carbon monoxide: Cal/OSHA PEL 25 ppm 8-hour average with a 200 ppm ceiling (federal construction PEL 50 ppm; NIOSH REL 35 ppm, which many monitors use as the alarm). Hydrogen sulfide: Cal/OSHA 10 ppm 8-hour average, 15 ppm short-term (15-minute) limit, and a 50 ppm ceiling never to be exceeded; federal construction 10 ppm. Carbon dioxide: 5,000 ppm PEL, 30,000 ppm STEL. The confined space limits are the same in both systems: oxygen 19.5 to 23.5 percent and 10 percent of the LEL. The app's permit defaults (O2 19.5-23.5, LEL 10, H2S 10, CO 25) already use this CO limit everywhere; a company program may set stricter limits, and 15 ppm H2S is a 15-minute limit, not a working level. None of this is a go/no-go: the entry supervisor and the company program decide.", "source": "8 CCR 5155 Table AC-1 (carbon monoxide, hydrogen sulfide, carbon dioxide rows); 29 CFR 1926.55 Appendix A; NIOSH Pocket Guide", "url": "https://www.dir.ca.gov/Title8/5155.html", "checked": "2026-11-20", "edition": "Title 8 section 5155 as posted on dir.ca.gov", "confidence": "high", "kind": "summary", "license": "gov-state", "note": "Same facts as ca-cal-osha-trench-and-confined-3 (this ord), now a CA state card (state field, title starts with the state)."}$kb$::jsonb
 where version = 'b3e91f6c47d2' and chunk->>'id' = $kb$ca-cal-osha-trench-and-confined-3$kb$
   and ($kb$sp-ca-confined-air-1$kb$ = $kb$ca-cal-osha-trench-and-confined-3$kb$ or not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = $kb$sp-ca-confined-air-1$kb$));
-- sp-wa-confined-1 replaces sp-wa-confined-1 (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-wa-confined-1", "state": "WA", "tier": "core", "supersedes": "sp-wa-confined-1", "title": "Washington confined space rule (chapter 296-809 WAC): one rule for all industries", "topic": "State safety plan: confined space", "text": "Washington has one confined space rule for all industries, chapter 296-809 WAC, instead of the federal construction rule; OSHA's adoption table lists it as different but at least as effective. Air numbers match federal: flammables over 10 percent of the LFL or LEL, oxygen below 19.5 or above 23.5 percent (296-809-099). Its definitions add: any physical hazard (electrical shock, moving parts) makes a space permit-required; where the opening is big enough to fully enter, a permit is needed even for partial body entry; excavations and pits are among its examples. Permit (read 2026-11-19): the same 15 items as the federal general industry list, in another order (296-809-50004), with equipment to detect a rise in hazard if ventilation stops (federal construction item (e)); available at entry (50002(5)); problems noted on it (50002(7)); kept 1 year (50006(2)). Air is tested with a calibrated, direct-reading instrument (60004(3)(a)). The app's permit form covers these items.", "source": "WAC 296-809-099 (WSR 18-02-071, eff. 2/5/18), 296-809-50002, 296-809-50004, 296-809-50006, 296-809-60004", "url": "https://lawfilesext.leg.wa.gov/Law/WACArchive/2024/htm/WAC%20296%20-809%20%20CHAPTER/WAC%20296%20-809%20-099.htm", "checked": "2026-11-21", "edition": "Chapter 296-809 WAC: permit sections read 2026-11-19; 296-809-099 as archived 2024, read 2026-11-21", "confidence": "medium", "kind": "summary", "license": "gov-state", "note": "Adds the 296-809-099 definitions (read 2026-11-21). \"Not re-read on 2026-11-20\" replaced by the dates in edition."}$kb$::jsonb
 where version = 'b3e91f6c47d2' and chunk->>'id' = $kb$sp-wa-confined-1$kb$
   and ($kb$sp-wa-confined-1$kb$ = $kb$sp-wa-confined-1$kb$ or not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = $kb$sp-wa-confined-1$kb$));
-- sp-mi-confined-2 replaces sp-mi-confined-2 (same row, same ord)
update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-mi-confined-2", "state": "MI", "tier": "core", "supersedes": "sp-mi-confined-2", "title": "Michigan confined space in construction: MIOSHA Part 35 adopts the federal rule", "topic": "State safety plan: confined space", "text": "Michigan's Construction Safety Standard Part 35, Confined Space in Construction, adopts 29 CFR 1926.1202 (definitions) through 1926.1212 (employee participation) by reference, except as amended in the rules (R 408.43510, via the scope rule R 408.43501(4)). That includes the federal permit items in 1926.1206, so a federal-style entry permit covers Michigan. Part 35 does not apply to work covered by Part 9 (excavation, trenching and shoring), Part 14 (tunnels, shafts, caissons, cofferdams), Part 504 (diving) or Part 665 (underground construction and compressed air); where another standard also covers a confined space hazard, both apply (R 408.43501(2), (3)). Part 35 has three rules: scope, provision of documents, and adopted standards. Work that is not construction (an owner's plant or utility staff) falls under MIOSHA's general industry rule, which MIOSHA lists as Part 90, Permit-Required Confined Spaces (read 2026-11-21; its text was not read here).", "source": "Mich. Admin. Code R 408.43501, R 408.43505, R 408.43510 (MIOSHA Part 35); MIOSHA confined spaces page", "url": "https://www.law.cornell.edu/regulations/michigan/Mich-Admin-Code-R-408-43501", "checked": "2026-11-21", "edition": "Part 35 as posted by Cornell LII, read 2026-11-20; MIOSHA page read 2026-11-21", "confidence": "medium", "kind": "summary", "license": "gov-state", "note": "Adds the Part 90 pointer (MIOSHA page read 2026-11-21)."}$kb$::jsonb
 where version = 'b3e91f6c47d2' and chunk->>'id' = $kb$sp-mi-confined-2$kb$
   and ($kb$sp-mi-confined-2$kb$ = $kb$sp-mi-confined-2$kb$ or not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = $kb$sp-mi-confined-2$kb$));

-- the version's row count (the Ask loader refuses a library whose rows don't match kb_versions.n)
update pb_ai.kb_versions v
   set n = c.n, counts = c.counts
  from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts
          from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
 where v.version = 'b3e91f6c47d2';
-- drop the saved search index so workers rebuild it from the rows
delete from pb_ai.kb_index_parts where version = 'b3e91f6c47d2';
delete from pb_ai.kb_index where version = 'b3e91f6c47d2';
-- checks: ords must stay 0..n-1 with no gaps, ids unique
do $chk$
declare n int; mx int; d int;
begin
  select count(*), max(ord), count(distinct chunk->>'id') into n, mx, d from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  if mx <> n - 1 then raise exception 'FAIL ord gap: % rows, max ord %', n, mx; end if;
  if d <> n then raise exception 'FAIL duplicate chunk id: % ids for % rows', d, n; end if;
  if (select v.n from pb_ai.kb_versions v where v.version = 'b3e91f6c47d2') <> n then raise exception 'FAIL kb_versions.n'; end if;
end $chk$;
commit;
